package ink.warrant.instrument

import java.util.UUID

class AcmeH2Driver : Driver {
    override val id: String = "acme-h2"
    override val label: String = "ACME-H2 Humidity Sensor"
    override val produces: Produces = Produces(
        unit = "%",
        min = 0.0,
        max = 100.0
    )
    override val matches: Match = Match(
        serviceUuids = listOf(UUID.fromString("6e400001-b5a3-f393-e0a9-e50e24dcca9e")),
        namePrefixes = listOf("ACME-H2")
    )
    override fun characteristicFor(services: List<UUID>): CharacteristicRef? {
        if (services.contains(UUID.fromString("6e400001-b5a3-f393-e0a9-e50e24dcca9e"))) {
            return CharacteristicRef(
                UUID.fromString("6e400001-b5a3-f393-e0a9-e50e24dcca9e"),
                UUID.fromString("6e400003-b5a3-f393-e0a9-e50e24dcca9e")
            )
        }
        return null
    }
    override fun decode(raw: ByteArray): Double? {
        if (raw.size < 4) return null
        if (raw[0] != 0x01.toByte()) return null
        val low = raw[1].toInt() and 0xFF
        val high = raw[2].toInt() and 0xFF
        val rawValue = (high shl 8) or low
        return rawValue.toDouble() / 100.0
    }
}

